/* C API of the Rust port of `src/text.c`, generated by mojo-anything. */
#ifndef TEXT_RS_H
#define TEXT_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

size_t count_words(const char *s);
int vowels(const char *s);
bool is_palindrome(const char *s);

/* The same functions under `mojo_anything_` names, for shadow runs. */
size_t mojo_anything_count_words(const char *s);
int mojo_anything_vowels(const char *s);
bool mojo_anything_is_palindrome(const char *s);

#endif /* TEXT_RS_H */
